BEGIN
  SELECT id INTO v_league_id FROM public.leagues WHERE slug = 'sdsap';
  IF v_league_id IS NULL THEN RETURN; END IF;
  SELECT id INTO v_season_id FROM public.seasons
    WHERE league_id = v_league_id AND name = 'Season 14';
  -- Fresh databases and disposable test databases do not contain this historical season.
  IF v_season_id IS NULL THEN RETURN; END IF;
  SELECT id INTO STRICT v_old_id FROM public.player_pool WHERE name = 'A Chung';
  SELECT id, name INTO STRICT v_new_id, v_name FROM public.player_pool WHERE name = 'Tiến MB';

  PERFORM pg_advisory_xact_lock(hashtextextended('league_replace_ratings:' || v_league_id::text, 0));
  PERFORM pg_advisory_xact_lock(hashtextextended('league_season_setup:' || v_season_id::text, 0));
  PERFORM 1 FROM public.seasons WHERE id = v_season_id FOR UPDATE;
  IF EXISTS (SELECT 1 FROM public.season_roster WHERE season_id = v_season_id AND pool_player_id = v_new_id)
    AND NOT EXISTS (SELECT 1 FROM public.season_roster WHERE season_id = v_season_id AND pool_player_id = v_old_id)
    AND EXISTS (SELECT 1 FROM public.league_players WHERE league_id = v_league_id AND pool_player_id = v_new_id AND initial_rating = 1800)
  THEN RETURN; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.seasons WHERE id = v_season_id AND status = 'active' AND format = 'team_duel')
    OR EXISTS (SELECT 1 FROM public.pickle_awards WHERE season_id = v_season_id)
  THEN RAISE EXCEPTION 'Season 14 must be active and unawarded for this correction'; END IF;

  -- Block concurrent writes while making this single-transaction historical identity correction.
  -- All foreign keys, score checks, award guards and deferred schedule checks remain enabled.
  ALTER TABLE public.players DISABLE TRIGGER players_guard_duel_roster;
  ALTER TABLE public.season_roster DISABLE TRIGGER roster_guard_duel_roster;
  ALTER TABLE public.matches DISABLE TRIGGER matches_guard_duel;
  ALTER TABLE public.matches DISABLE TRIGGER ab_guard_pickle_bets;
  ALTER TABLE public.players DISABLE TRIGGER guard_pickle_roster;
  LOCK TABLE public.league_players, public.rating_history, public.pickle_bets,
    public.pickle_wallets, public.pickle_transactions, public.pickle_bet_settlements
    IN SHARE ROW EXCLUSIVE MODE;

  SELECT replay_input INTO v_input FROM (select jsonb_build_object(
'expectedRevision',(select revision from public.rating_state where league_id=v_league_id),
'pool',(select jsonb_agg(jsonb_build_object('id',pool_player_id,'initial_rating',initial_rating) order by pool_player_id) from public.league_players where league_id=v_league_id),
'finishedMatches',(select jsonb_agg(row_to_json(x) order by season_starts_at, coalesce(result_recorded_at::text,''),id) from (
 select m.id,m.season_id,m.round_number,s.starts_at as season_starts_at,m.result_recorded_at,m.winner_team_id,m.home_team_id,m.away_team_id,m.home_score,m.away_score,m.home_pool_player_ids,m.away_pool_player_ids,
 (select jsonb_agg(jsonb_build_object('pool_player_id',p.pool_player_id)) from public.players p where p.team_id=m.home_team_id) as home_players,
 (select jsonb_agg(jsonb_build_object('pool_player_id',p.pool_player_id)) from public.players p where p.team_id=m.away_team_id) as away_players
 from public.matches m join public.seasons s on s.id=m.season_id where s.league_id=v_league_id and m.status='completed') x)
) as replay_input) source;
  IF md5(v_input::text) <> '5f199fee2fe2bb4c2be6259c72100967'
    OR (v_input->>'expectedRevision')::bigint <> 328
  THEN RAISE EXCEPTION 'Source data changed; regenerate and review the rating replay' USING ERRCODE = '40001'; END IF;
  IF EXISTS (
    SELECT 1 FROM jsonb_array_elements(v_payload->'baseline') b
    JOIN public.league_players lp ON lp.league_id = v_league_id
      AND lp.pool_player_id = (v_input->'pool'->((b->>0)::integer)->>'id')::uuid
    WHERE abs(lp.rating - (b->>1)::double precision) > 0.0000001
      OR abs(lp.rating_deviation - (b->>2)::double precision) > 0.0000001
  ) THEN RAISE EXCEPTION 'Canonical replay does not reproduce the stored baseline'; END IF;
  IF (SELECT count(*) FROM public.matches WHERE season_id = v_season_id AND status = 'completed') <> 21
    OR (SELECT count(*) FROM public.matches WHERE season_id = v_season_id) <> 21
    OR (SELECT count(*) FROM public.matches WHERE season_id = v_season_id
      AND v_old_id = ANY(home_pool_player_ids || away_pool_player_ids)) <> 6
    OR (SELECT count(*) FROM public.season_roster WHERE season_id = v_season_id) <> 14
    OR (SELECT count(*) FROM public.players WHERE season_id = v_season_id AND pool_player_id = v_old_id) <> 1
    OR EXISTS (SELECT 1 FROM public.rating_history WHERE pool_player_id = v_new_id AND match_id IS NOT NULL)
  THEN RAISE EXCEPTION 'Unexpected Season 14 substitution scope'; END IF;

  SELECT jsonb_agg(to_jsonb(m) - 'home_pool_player_ids' - 'away_pool_player_ids' ORDER BY id)
    INTO v_scores_before FROM public.matches m WHERE season_id = v_season_id;
  SELECT md5(coalesce(jsonb_agg(to_jsonb(m) ORDER BY m.id)::text, '[]'))
    INTO v_other_seasons_before FROM public.matches m JOIN public.seasons s ON s.id = m.season_id
    WHERE s.league_id = v_league_id AND m.season_id <> v_season_id;
  SELECT jsonb_agg(to_jsonb(b) - 'home_ids' - 'away_ids' ORDER BY id)
    INTO v_bets_before FROM public.pickle_bets b WHERE season_id = v_season_id;
  SELECT jsonb_agg(jsonb_build_object('match_id', h.match_id, 'rating', round(h.rating::numeric, 8), 'rating_deviation', round(h.rating_deviation::numeric, 8)) ORDER BY h.match_id)
    INTO v_old_history_before FROM public.rating_history h JOIN public.matches m ON m.id = h.match_id
    WHERE h.league_id = v_league_id AND h.pool_player_id = v_old_id AND m.season_id <> v_season_id;
  SELECT md5(jsonb_build_object(
    'wallets', (SELECT jsonb_agg(to_jsonb(w) ORDER BY pool_player_id) FROM public.pickle_wallets w WHERE league_id = v_league_id),
    'transactions', (SELECT jsonb_agg(to_jsonb(t) ORDER BY id) FROM public.pickle_transactions t WHERE league_id = v_league_id),
    'settlements', (SELECT jsonb_agg(to_jsonb(s) ORDER BY id) FROM public.pickle_bet_settlements s WHERE league_id = v_league_id)
  )::text) INTO v_finance_before;

  UPDATE public.season_roster SET pool_player_id = v_new_id
    WHERE season_id = v_season_id AND pool_player_id = v_old_id;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  IF v_count <> 1 THEN RAISE EXCEPTION 'Expected exactly one roster substitution'; END IF;
  UPDATE public.players SET pool_player_id = v_new_id, name = v_name
    WHERE season_id = v_season_id AND pool_player_id = v_old_id;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  IF v_count <> 1 THEN RAISE EXCEPTION 'Expected exactly one squad substitution'; END IF;
  UPDATE public.matches SET
    home_pool_player_ids = array_replace(home_pool_player_ids, v_old_id, v_new_id),
    away_pool_player_ids = array_replace(away_pool_player_ids, v_old_id, v_new_id)
    WHERE season_id = v_season_id AND v_old_id = ANY(home_pool_player_ids || away_pool_player_ids);
  GET DIAGNOSTICS v_count = ROW_COUNT;
  IF v_count <> 6 THEN RAISE EXCEPTION 'Expected exactly six lineup corrections'; END IF;
  UPDATE public.pickle_bets b SET
    home_ids = pickle_private.side_ids(m, true),
    away_ids = pickle_private.side_ids(m, false)
    FROM public.matches m WHERE m.id = b.match_id AND b.season_id = v_season_id
      AND v_old_id = ANY(b.home_ids || b.away_ids);
  GET DIAGNOSTICS v_count = ROW_COUNT;
  IF v_count <> 9 THEN RAISE EXCEPTION 'Expected exactly nine existing bet lineup snapshots'; END IF;
  UPDATE public.league_players SET initial_rating = 1800
    WHERE league_id = v_league_id AND pool_player_id = v_new_id AND initial_rating = 2100;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  IF v_count <> 1 THEN RAISE EXCEPTION 'Starting rating changed before correction'; END IF;

  SELECT jsonb_agg(jsonb_build_object(
    'pool_player_id', v_input->'pool'->((e->>0)::integer)->>'id',
    'match_id', CASE WHEN e->1 = 'null'::jsonb THEN NULL
      ELSE v_input->'finishedMatches'->((e->>1)::integer)->>'id' END,
    'rating', (e->>2)::double precision, 'rating_deviation', (e->>3)::double precision,
    'sequence', (e->>4)::integer, 'recorded_at', e->>5
  )) INTO v_history FROM jsonb_array_elements(v_payload->'history') e;
  SELECT jsonb_agg(jsonb_build_object(
    'id', v_input->'pool'->((e->>0)::integer)->>'id',
    'rating', (e->>1)::double precision, 'rating_deviation', (e->>2)::double precision,
    'volatility', (e->>3)::double precision
  )) INTO v_ratings FROM jsonb_array_elements(v_payload->'ratings') e;
  PERFORM public.replace_ratings_atomic(v_league_id, v_history, v_ratings, 328);

  PERFORM public.validate_league_duel_season(v_season_id);
  SET CONSTRAINTS ALL IMMEDIATE;
  ALTER TABLE public.players ENABLE TRIGGER players_guard_duel_roster;
  ALTER TABLE public.season_roster ENABLE TRIGGER roster_guard_duel_roster;
  ALTER TABLE public.matches ENABLE TRIGGER matches_guard_duel;
  ALTER TABLE public.matches ENABLE TRIGGER ab_guard_pickle_bets;
  ALTER TABLE public.players ENABLE TRIGGER guard_pickle_roster;

  SELECT jsonb_agg(to_jsonb(m) - 'home_pool_player_ids' - 'away_pool_player_ids' ORDER BY id)
    INTO v_scores_after FROM public.matches m WHERE season_id = v_season_id;
  SELECT md5(coalesce(jsonb_agg(to_jsonb(m) ORDER BY m.id)::text, '[]'))
    INTO v_other_seasons_after FROM public.matches m JOIN public.seasons s ON s.id = m.season_id
    WHERE s.league_id = v_league_id AND m.season_id <> v_season_id;
  SELECT jsonb_agg(to_jsonb(b) - 'home_ids' - 'away_ids' ORDER BY id)
    INTO v_bets_after FROM public.pickle_bets b WHERE season_id = v_season_id;
  SELECT jsonb_agg(jsonb_build_object('match_id', h.match_id, 'rating', round(h.rating::numeric, 8), 'rating_deviation', round(h.rating_deviation::numeric, 8)) ORDER BY h.match_id)
    INTO v_old_history_after FROM public.rating_history h JOIN public.matches m ON m.id = h.match_id
    WHERE h.league_id = v_league_id AND h.pool_player_id = v_old_id AND m.season_id <> v_season_id;
  SELECT md5(jsonb_build_object(
    'wallets', (SELECT jsonb_agg(to_jsonb(w) ORDER BY pool_player_id) FROM public.pickle_wallets w WHERE league_id = v_league_id),
    'transactions', (SELECT jsonb_agg(to_jsonb(t) ORDER BY id) FROM public.pickle_transactions t WHERE league_id = v_league_id),
    'settlements', (SELECT jsonb_agg(to_jsonb(s) ORDER BY id) FROM public.pickle_bet_settlements s WHERE league_id = v_league_id)
  )::text) INTO v_finance_after;
  IF v_scores_before IS DISTINCT FROM v_scores_after
    OR v_other_seasons_before IS DISTINCT FROM v_other_seasons_after
    OR v_bets_before IS DISTINCT FROM v_bets_after
    OR v_finance_before IS DISTINCT FROM v_finance_after
    OR v_old_history_before IS DISTINCT FROM v_old_history_after
  THEN RAISE EXCEPTION 'Correction altered protected results, prior seasons, or financial state'; END IF;
  IF (SELECT count(*) FROM public.rating_history h JOIN public.matches m ON m.id = h.match_id
    WHERE m.season_id = v_season_id AND h.pool_player_id = v_new_id) <> 6
    OR EXISTS (SELECT 1 FROM public.rating_history h JOIN public.matches m ON m.id = h.match_id
      WHERE m.season_id = v_season_id AND h.pool_player_id = v_old_id)
    OR EXISTS (SELECT 1 FROM public.players WHERE season_id = v_season_id AND pool_player_id = v_old_id)
    OR EXISTS (SELECT 1 FROM public.pickle_bets b JOIN public.matches m ON m.id = b.match_id
      WHERE b.season_id = v_season_id AND (b.home_ids IS DISTINCT FROM pickle_private.side_ids(m,true)
        OR b.away_ids IS DISTINCT FROM pickle_private.side_ids(m,false)))
    OR NOT EXISTS (SELECT 1 FROM public.rating_history WHERE league_id = v_league_id
      AND pool_player_id = v_new_id AND match_id IS NULL AND rating = 1800 AND sequence = (
        SELECT min(sequence) FROM public.rating_history WHERE league_id = v_league_id AND pool_player_id = v_new_id))
  THEN RAISE EXCEPTION 'Corrected roster, match credit, starting rating, or bet snapshots failed verification'; END IF;
END
$repair$;
